PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, admin INTEGER NOT NULL DEFAULT 0, can_upload INTEGER NOT NULL DEFAULT 0, blocked_genres TEXT NOT NULL DEFAULT '[]', blocked_collections TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, genre TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL, owner TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS collections(id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS collection_items(collection_id TEXT REFERENCES collections(id) ON DELETE CASCADE, media_id TEXT REFERENCES media(id) ON DELETE CASCADE, position INTEGER NOT NULL, PRIMARY KEY(collection_id, media_id));
CREATE TABLE IF NOT EXISTS progress(user_id TEXT REFERENCES users(id) ON DELETE CASCADE, media_id TEXT REFERENCES media(id) ON DELETE CASCADE, seconds REAL NOT NULL DEFAULT 0, updated INTEGER NOT NULL, PRIMARY KEY(user_id,media_id));
CREATE TABLE IF NOT EXISTS pairing(id TEXT PRIMARY KEY, pin TEXT NOT NULL UNIQUE, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES('gpu','true');
CREATE INDEX IF NOT EXISTS media_created ON media(created DESC);
CREATE INDEX IF NOT EXISTS membership_media ON collection_items(media_id);
